      "tipo": "GC",
      "causa_raiz": "Alocação massiva de lixo na memória heap a cada frame devido à concatenação cumulativa de strings ('s += i.ToString()') e alocações repetidas de novos arrays ('new object[10000]'). Isso gera picos de Garbage Collector de até 23.18ms, congelando a execução da CPU muito além do orçamento de 16.7ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private object[][] _reusableArrays;
        private MaterialPropertyBlock _propertyBlock;

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(gcConcatIterations * 4);
            _propertyBlock = new MaterialPropertyBlock();
            if (gcArrayAllocs > 0)
            {
                _reusableArrays = new object[gcArrayAllocs][];
                for (int i = 0; i < gcArrayAllocs; i++)
                {
                    _reusableArrays[i] = new object[10000];
                }
            }
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);
            if (useUniqueMaterials && clone.TryGetComponent<Renderer>(out var renderer))
            {
                renderer.GetPropertyBlock(_propertyBlock);
                _propertyBlock.SetColor("_Color", new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                renderer.SetPropertyBlock(_propertyBlock);
            }
        }
    }
}",
      "explicacao_didatica": "Strings em C# são imutáveis; cada vez que usamos '+=' em uma string dentro de um loop, criamos um novo texto temporário na memória. O Garbage Collector precisa pausar todo o jogo para limpar esses milhares de textos acumulados, causando engasgos (stutters). Substituímos isso por StringBuilder reutilizável e pré-alocação de memória, eliminando a criação de lixo no loop de renderização."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva de 'GameObject.FindObjectsOfType<GameObject>()' dentro do Update(). Essa função percorre todos os nós de todas as árvores de objetos ativas na cena várias vezes por frame, gerando um custo de busca O(N) gigantesco na CPU (picos de 118.27ms) e alocando arrays extras a cada chamada.",
      "codigo_refatorado": "using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class SceneObjectRegistry : MonoBehaviour
    {
        private static readonly List<GameObject> _registeredObjects = new List<GameObject>(2048);

        public static IReadOnlyList<GameObject> ActiveObjects => _registeredObjects;

        public static void Register(GameObject obj)
        {
            if (!_registeredObjects.Contains(obj))
            {
                _registeredObjects.Add(obj);
            }
        }

        public static void Unregister(GameObject obj)
        {
            _registeredObjects.Remove(obj);
        }
    }
}",
      "explicacao_didatica": "A função FindObjectsOfType vasculha a memória inteira da cena do Unity à procura de objetos, o que é análogo a ler um livro inteiro do começo ao fim toda vez que você precisa achar uma palavra. Em vez de procurar no Update(), objetos devem se cadastrar em uma lista estática (registro/cache) ao nascerem e se descadastrarem ao serem destruídos, tornando o acesso instantâneo."
    }
  ],
  "dicas_level_design": null
}

